import{_ as t,o as i,c as s,a5 as l}from"./chunks/framework.C1a7WKBV.js";const k=JSON.parse('{"title":"Ollama 与 LM Studio 本地 AI 入门","description":"根据硬件和操作习惯选择 Ollama 或 LM Studio，在本机运行模型并验证本地 API。","frontmatter":{"title":"Ollama 与 LM Studio 本地 AI 入门","description":"根据硬件和操作习惯选择 Ollama 或 LM Studio，在本机运行模型并验证本地 API。"},"headers":[],"relativePath":"clients/local-ai.md","filePath":"clients/local-ai.md","lastUpdated":1788838685000}'),e={name:"clients/local-ai.md"};function h(d,a,o,n,r,p){return i(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="ollama-与-lm-studio-本地-ai-入门" tabindex="-1">Ollama 与 LM Studio 本地 AI 入门 <a class="header-anchor" href="#ollama-与-lm-studio-本地-ai-入门" aria-label="Permalink to &quot;Ollama 与 LM Studio 本地 AI 入门&quot;">​</a></h1><p>本地模型把推理运行在自己的电脑上，适合离线、隐私敏感和开发调试。它不是自动等于“免费又更强”：你仍要承担硬件占用、模型下载、速度和维护成本。</p><h2 id="_1-先选-ollama-还是-lm-studio" tabindex="-1">1. 先选 Ollama 还是 LM Studio <a class="header-anchor" href="#_1-先选-ollama-还是-lm-studio" aria-label="Permalink to &quot;1. 先选 Ollama 还是 LM Studio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>推荐</th><th>原因</th></tr></thead><tbody><tr><td>第一次体验本地模型、喜欢图形界面</td><td>LM Studio</td><td>搜索、下载、加载和聊天都可视化</td></tr><tr><td>需要脚本、API、服务器或终端集成</td><td>Ollama</td><td>命令简洁，适合自动化</td></tr><tr><td>想查看模型文件、量化与运行参数</td><td>LM Studio</td><td>界面信息更直观</td></tr><tr><td>想接入其他开发工具</td><td>Ollama</td><td>本地服务与集成路径直接</td></tr></tbody></table><h2 id="_2-硬件与模型大小" tabindex="-1">2. 硬件与模型大小 <a class="header-anchor" href="#_2-硬件与模型大小" aria-label="Permalink to &quot;2. 硬件与模型大小&quot;">​</a></h2><p><a href="https://lmstudio.ai/docs/app/system-requirements" target="_blank" rel="noreferrer">LM Studio 官方系统要求</a>建议 16GB 以上内存；Windows x64 处理器需要 AVX2，并建议至少 4GB 独立显存。Ollama 支持 macOS、Windows 与 Linux，具体安装以<a href="https://docs.ollama.com/quickstart" target="_blank" rel="noreferrer">官方快速开始</a>为准。</p><p>新手可按这个保守规则起步：</p><table tabindex="0"><thead><tr><th>可用内存</th><th>起步模型规模</th><th>建议</th></tr></thead><tbody><tr><td>8GB</td><td>1B–4B 的量化模型</td><td>关闭其他大应用，缩短上下文</td></tr><tr><td>16GB</td><td>4B–8B 的量化模型</td><td>日常问答和轻量代码最合适</td></tr><tr><td>32GB</td><td>8B–14B，视量化而定</td><td>质量更好，仍需观察占用</td></tr><tr><td>64GB+ 或大显存</td><td>更大模型</td><td>先确认实际任务收益再下载</td></tr></tbody></table><p>模型参数量、量化方式、上下文长度都会影响内存，表格只是起点，不是保证。</p><h2 id="_3-路线-a-ollama" tabindex="-1">3. 路线 A：Ollama <a class="header-anchor" href="#_3-路线-a-ollama" aria-label="Permalink to &quot;3. 路线 A：Ollama&quot;">​</a></h2><h3 id="_3-1-安装并确认服务" tabindex="-1">3.1 安装并确认服务 <a class="header-anchor" href="#_3-1-安装并确认服务" aria-label="Permalink to &quot;3.1 安装并确认服务&quot;">​</a></h3><p>从 <a href="https://ollama.com/download" target="_blank" rel="noreferrer">Ollama 官网</a>下载对应系统版本。安装后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span></span></code></pre></div><p>新版交互菜单可以选择并运行模型。也可以按模型库页面提供的名称执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODEL_NAME</span></span></code></pre></div><h3 id="_3-2-验证本地-api" tabindex="-1">3.2 验证本地 API <a class="header-anchor" href="#_3-2-验证本地-api" aria-label="Permalink to &quot;3.2 验证本地 API&quot;">​</a></h3><p>官方快速开始给出的本地 API 默认位于 <code>http://localhost:11434</code>。替换为你已经下载的模型名：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:11434/api/chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;model&quot;: &quot;MODEL_NAME&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;messages&quot;: [{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;只回复：本地连接成功&quot;}],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;stream&quot;: false</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span></code></pre></div><h3 id="_3-3-常用管理命令" tabindex="-1">3.3 常用管理命令 <a class="header-anchor" href="#_3-3-常用管理命令" aria-label="Permalink to &quot;3.3 常用管理命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODEL_NAME</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODEL_NAME</span></span></code></pre></div><p>删除前确认模型名；模型文件通常很大，下载时注意磁盘空间。</p><h2 id="_4-路线-b-lm-studio" tabindex="-1">4. 路线 B：LM Studio <a class="header-anchor" href="#_4-路线-b-lm-studio" aria-label="Permalink to &quot;4. 路线 B：LM Studio&quot;">​</a></h2><h3 id="_4-1-安装、搜索与加载" tabindex="-1">4.1 安装、搜索与加载 <a class="header-anchor" href="#_4-1-安装、搜索与加载" aria-label="Permalink to &quot;4.1 安装、搜索与加载&quot;">​</a></h3><ol><li>从 <a href="https://lmstudio.ai/" target="_blank" rel="noreferrer">LM Studio 官网</a>下载并启动。</li><li>在 Discover 中搜索模型，优先选择与内存匹配的 GGUF 量化版本。</li><li>下载后进入 Chat，加载模型并发送一句测试消息。</li><li>若内存不足，换更小参数量或更高压缩量化，不要盲目加大上下文。</li></ol><h3 id="_4-2-启动本地-api" tabindex="-1">4.2 启动本地 API <a class="header-anchor" href="#_4-2-启动本地-api" aria-label="Permalink to &quot;4.2 启动本地 API&quot;">​</a></h3><p>LM Studio 的 <a href="https://lmstudio.ai/docs/developer/rest/quickstart" target="_blank" rel="noreferrer">REST API 快速开始</a>说明，可在 Developer 页面启动服务，也可以运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>默认地址是 <code>http://localhost:1234</code>。先列出模型：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:1234/api/v1/models</span></span></code></pre></div><p>默认服务可能不要求认证。只绑定本机使用，不要直接暴露到公网；需要局域网访问时启用 API Token、限制防火墙来源并确认数据政策。</p><h2 id="_5-如何判断-真的在本地" tabindex="-1">5. 如何判断“真的在本地” <a class="header-anchor" href="#_5-如何判断-真的在本地" aria-label="Permalink to &quot;5. 如何判断“真的在本地”&quot;">​</a></h2><ol><li>模型文件已经下载到本机。</li><li>推理时系统的 CPU、GPU 或统一内存占用明显上升。</li><li>API 地址是 <code>localhost</code> 或 <code>127.0.0.1</code>。</li><li>断网后仍能对已下载模型进行对话。</li><li>没有启用会把内容发给外部服务的搜索、插件或 MCP 工具。</li></ol><p>“模型本地”不代表整个工作流都本地，联网插件仍可能发送数据。</p><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to &quot;6. 常见问题&quot;">​</a></h2><h3 id="_6-1-回答很慢" tabindex="-1">6.1 回答很慢 <a class="header-anchor" href="#_6-1-回答很慢" aria-label="Permalink to &quot;6.1 回答很慢&quot;">​</a></h3><p>换更小模型或更激进的量化，缩短上下文，关闭占显存程序。首次加载慢、后续生成正常通常是模型载入时间。</p><h3 id="_6-2-程序直接退出或内存爆满" tabindex="-1">6.2 程序直接退出或内存爆满 <a class="header-anchor" href="#_6-2-程序直接退出或内存爆满" aria-label="Permalink to &quot;6.2 程序直接退出或内存爆满&quot;">​</a></h3><p>模型或上下文超出硬件能力。先从 4B–8B 量化模型开始，不要同时加载多个模型。</p><h3 id="_6-3-客户端连接不到本地-api" tabindex="-1">6.3 客户端连接不到本地 API <a class="header-anchor" href="#_6-3-客户端连接不到本地-api" aria-label="Permalink to &quot;6.3 客户端连接不到本地 API&quot;">​</a></h3><p>确认服务正在运行、端口正确、客户端需要的协议是否兼容。用 <code>curl</code> 先证明服务端正常，再检查客户端配置。</p><h2 id="_7-完成标准" tabindex="-1">7. 完成标准 <a class="header-anchor" href="#_7-完成标准" aria-label="Permalink to &quot;7. 完成标准&quot;">​</a></h2><ul><li>[ ] 能说明本地模型的隐私边界与硬件代价。</li><li>[ ] 已成功加载一个匹配硬件的模型。</li><li>[ ] 断网后仍能完成一次对话。</li><li>[ ] 能用 <code>curl</code> 验证本地 API。</li><li>[ ] 本地服务没有直接暴露到公网。</li></ul>`,42)])])}const u=t(e,[["render",h]]);export{k as __pageData,u as default};
